B.alI=s(["\xa1Una menos, {n}! Sigue as\xed \ud83d\udcaa","\xa1Bien comido! Cada plato cuenta \ud83c\udf7d\ufe0f","\xa1Eso es! Tu cuerpo te lo agradece \ud83d\ude4c","\xa1Hecho! Paso a paso se llega \ud83c\udfaf","\xa1Muy bien! A por la siguiente \ud83c\udf45"],t.s)
B.aNz=s(["\xa1Todas las comidas hechas! D\xeda de campeonato \ud83c\udfc6","\xa15 de 5, {n}! D\xeda perfecto \ud83c\udf89","\xa1Men\xfa completo! As\xed se hace \ud83e\udd73"],t.s)
B.amd=s(["\xa1Objetivo de agua cumplido! \ud83d\udca7","\xa1Agua al d\xeda, {n}! \ud83d\udca7"],t.s)
B.ajv=s(["\xa1Creatina tomada! La constancia es la clave \ud83d\udc8a","Un d\xeda m\xe1s de creatina. \xa1No falles ma\xf1ana! \ud83d\udc8a"],t.s)
